```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/token"
	"io/ioutil"
	"os"

	"github.com/mjibson/go-avro/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Parse the Go source code
	file, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		fmt.Printf("Error reading file: %v\n", err)
		return
	}
	var tree *ast.File
	err = token.NewScanner(file).Scan(tree)
	if err != nil {
		fmt.Printf("Error parsing file: %v\n", err)
		return
	}

	// Find the struct definition
	for _, decl := range tree.Decls {
		if ast.IsExported(decl.Name) && decl.Type == nil {
			continue // Skip if not exported or has no type (i.e., anonymous structs)
		}
		if decl.Name.Name == structName {
			break
		}
	}

	if decl == nil {
		fmt.Printf("Struct '%s' not found in file %q.\n", structName, sourceFile)
		return
	}

	// Extract the field names and types from the struct declaration
	fieldDefs := make([]schema.FieldDefinition, 0, len(decl.Fields))
	for i, f := range decl.Fields {
		name := fmt.Sprintf("%d", i+1)
		typ := f.Type.String()
		fieldDefs = append(fieldDefs, schema.FieldDefinition{Field: &name, Type: typ})
	}

	// Generate the Avro schema
	schemaStr, err := schema.GenerateAvroSchema(&fieldDefs)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		return
	}

	// Write the schema to a file
	outFile, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		fmt.Printf("Error creating file: %v\n", err)
		return
	}
	defer outFile.Close()

	_, err = outFile.Write([]byte(schemaStr))
	if err != nil {
		fmt.Printf("Error writing schema to file: %v\n", err)
		return
	}

	fmt.Printf("Generated Avro schema saved to %s.avsc\n", structName)
}
```

### How to Use This Program:
1. Save this program into a file called `script.go`.
2. Compile the program using `go build -o script script.go`.
3. Run the compiled program with the following command:

   ```sh
   ./script your_source_file.go my_struct_name
   ```

4. Replace `your_source_file.go` with the path to your Go source file containing the struct you want to convert.
5. Replace `my_struct_name` with the name of the struct you're interested in.

The program will read the struct definition from the specified Go source file, create an Avro schema based on the fields defined in the struct, and save the resulting Avro schema to a file named `struct_name.avsc`.

### Note:
This example assumes that the Go source file contains valid Go syntax for defining a struct. If the struct definition is invalid, the program will likely fail to compile and may not find the desired struct.

